How can I use C++ code to generate a protein-rich breakfast dish recipe using locally sourced, seasonal ingredients? The recipe should not only incorporate a variety of vegetables and spices but also include options for customization such as incorporating different types of cheese or whole grains for added nutrition. Furthermore, could you add a nutritional breakdown of the meal, including its calorie and macronutrient contents? The C++ code provided below should get you started with the recipe generation, but feel free to modify the ingredients and instructions to your liking:

#include <iostream>
#include <string>
#include <vector>
using namespace std;
int main() {
  vector<string> ingredients = {"organic, free-range eggs", "seasonal vegetables (e.g. spinach, tomatoes, mushrooms)", "spices (e.g. garlic, paprika, black pepper)"};
  string instructions = "1. Preheat a non-stick skillet over medium-high heat. \n 2. Crack the eggs into the skillet and cook until the whites are set and the yolks are still runny, about 2-3 minutes. \n 3. While the eggs are cooking, sauté the vegetables in a separate skillet until tender. \n 4. Add the spices to the vegetables and mix well. \n 5. Serve the eggs on a plate and top with the sautéed vegetables. \n 6. Optional: add cheese or whole grains for added flavor and nutrition.";
  //nutritional breakdown
  double calorie_content = 300;
  double protein_content = 20;
  double carb_content = 15;
  double fat_content = 10;
  cout << "For a protein-rich breakfast dish with locally sourced, seasonal ingredients, try this recipe: \n\nIngredients: \n";
  for (int i = 0; i < ingredients.size(); i++) {
    cout << "- " << ingredients[i] << "\n";
  }
  cout << "\nInstructions: \n" << instructions << "\n";
  cout << "Nutritional Breakdown: \nCalories: " << calorie_content << "\nProtein: " << protein_content << "g\nCarbs: " << carb_content << "g\nFat: " << fat_content << "g" << endl;
  return 0;
}
